[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>IPL 2026 Ball-by-Ball Analytics Report</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
<style>
:root {
  --bg: #0f1117;
  --surface: #1a1d29;
  --surface2: #242836;
  --border: #2e3347;
  --text: #e4e7f1;
  --text-dim: #8b90a5;
  --accent: #6366f1;
  --accent-light: #818cf8;
  --green: #22c55e;
  --red: #ef4444;
  --orange: #f59e0b;
  --cyan: #06b6d4;
  --pink: #ec4899;
  --purple: #a855f7;
}
* { margin: 0; padding: 0; box-sizing: border-box; }
body { font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; background: var(--bg); color: var(--text); line-height: 1.6; }
.container { max-width: 1300px; margin: 0 auto; padding: 20px 32px; }
header { text-align: center; padding: 48px 20px 32px; border-bottom: 1px solid var(--border); margin-bottom: 40px; }
header h1 { font-size: 2.4rem; font-weight: 800; letter-spacing: -0.03em; background: linear-gradient(135deg, var(--accent-light), var(--cyan)); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
header .subtitle { color: var(--text-dim); font-size: 1rem; margin-top: 8px; }
header .meta { display: flex; justify-content: center; gap: 32px; margin-top: 16px; font-size: 0.85rem; color: var(--text-dim); }
header .meta span { display: flex; align-items: center; gap: 6px; }

.section { margin-bottom: 48px; }
.section-title { font-size: 1.5rem; font-weight: 700; margin-bottom: 20px; padding-bottom: 10px; border-bottom: 2px solid var(--accent); display: inline-block; }

/* KPI Dashboard */
.kpi-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px; margin-bottom: 48px; }
.kpi-card { background: var(--surface); border: 1px solid var(--border); border-radius: 12px; padding: 24px 20px; text-align: center; transition: transform 0.15s; }
.kpi-card:hover { transform: translateY(-2px); }
.kpi-value { font-size: 2.2rem; font-weight: 800; letter-spacing: -0.02em; }
.kpi-label { font-size: 0.78rem; color: var(--text-dim); text-transform: uppercase; letter-spacing: 0.08em; margin-top: 6px; }
.kpi-desc { font-size: 0.72rem; color: var(--text-dim); margin-top: 4px; opacity: 0.7; }
.kpi-card:nth-child(1) .kpi-value { color: var(--accent-light); }
.kpi-card:nth-child(2) .kpi-value { color: var(--green); }
.kpi-card:nth-child(3) .kpi-value { color: var(--orange); }
.kpi-card:nth-child(4) .kpi-value { color: var(--red); }
.kpi-card:nth-child(5) .kpi-value { color: var(--cyan); }

/* Overview Stats */
.overview-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-bottom: 24px; }
.stat-box { background: var(--surface); border: 1px solid var(--border); border-radius: 8px; padding: 16px; }
.stat-box .val { font-size: 1.6rem; font-weight: 700; color: var(--accent-light); }
.stat-box .lbl { font-size: 0.75rem; color: var(--text-dim); text-transform: uppercase; letter-spacing: 0.05em; }

/* Tables */
table { width: 100%; border-collapse: collapse; background: var(--surface); border-radius: 12px; overflow: hidden; border: 1px solid var(--border); margin-bottom: 20px; }
th { background: var(--surface2); padding: 12px 14px; text-align: left; font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-dim); font-weight: 600; }
td { padding: 10px 14px; border-top: 1px solid var(--border); font-size: 0.88rem; }
tr:hover td { background: rgba(99,102,241,0.05); }
.num { text-align: right; font-variant-numeric: tabular-nums; }
.highlight { color: var(--accent-light); font-weight: 700; }
.sr-high { color: var(--green); font-weight: 600; }
.sr-low { color: var(--red); font-weight: 600; }

/* Charts */
.chart-row { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-bottom: 24px; }
.chart-box { background: var(--surface); border: 1px solid var(--border); border-radius: 12px; padding: 20px; }
.chart-box h3 { font-size: 0.95rem; margin-bottom: 12px; color: var(--text-dim); }
.chart-full { grid-column: span 2; }
canvas { max-height: 380px; }

/* Phase badge */
.phase-badge { display: inline-block; padding: 2px 8px; border-radius: 4px; font-size: 0.72rem; font-weight: 600; }
.phase-pp { background: rgba(99,102,241,0.2); color: var(--accent-light); }
.phase-mid { background: rgba(34,197,94,0.2); color: var(--green); }
.phase-death { background: rgba(239,68,68,0.2); color: var(--red); }

/* Venue table short name */
.venue-short { max-width: 220px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* Bar indicator */
.bar-cell { position: relative; }
.bar-fill { position: absolute; left: 0; top: 0; bottom: 0; border-radius: 0 4px 4px 0; opacity: 0.12; }

/* Responsive */
@media (max-width: 900px) {
  .kpi-grid { grid-template-columns: repeat(3, 1fr); }
  .chart-row { grid-template-columns: 1fr; }
  .chart-full { grid-column: span 1; }
  .overview-grid { grid-template-columns: repeat(2, 1fr); }
}

footer { text-align: center; padding: 32px 0; color: var(--text-dim); font-size: 0.78rem; border-top: 1px solid var(--border); margin-top: 40px; }

.insight { background: linear-gradient(135deg, rgba(99,102,241,0.08), rgba(6,182,212,0.08)); border-left: 3px solid var(--accent); padding: 12px 16px; border-radius: 0 8px 8px 0; margin: 16px 0; font-size: 0.88rem; }
.insight strong { color: var(--accent-light); }
</style>
</head>
